"use client";

import * as SwitchPrimitive from "@radix-ui/react-switch";

import { cn } from "@/lib/utils";

const Switch = ({
  className,
  ...props
}: React.ComponentProps<typeof SwitchPrimitive.Root>) => (
  <SwitchPrimitive.Root
    data-slot="switch"
    className={cn(
      "peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent shadow-xs transition-[color,box-shadow,background-color] outline-none",
      "bg-input",
      "data-[state=checked]:bg-primary",
      "focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]",
      "disabled:cursor-not-allowed disabled:opacity-50",
      "aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
      className,
    )}
    {...props}
  >
    <SwitchPrimitive.Thumb
      data-slot="switch-thumb"
      className={cn(
        "bg-background pointer-events-none block size-4 rounded-full shadow-sm ring-0 transition-transform",
        "data-[state=checked]:translate-x-4",
        "data-[state=unchecked]:translate-x-0",
      )}
    />
  </SwitchPrimitive.Root>
);

export { Switch };
export default Switch;

"use client";

import { useState } from "react";

import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

export function SwitchDemo() {
  const [notifications, setNotifications] = useState(true);

  return (
    <div className="flex flex-col gap-6">
      {/* Basic */}
      <div className="flex items-center gap-2">
        <Switch id="sw-basic" defaultChecked sounds />
        <Label htmlFor="sw-basic">Airplane mode</Label>
      </div>

      {/* Controlled with status */}
      <div className="flex items-center justify-between rounded-lg border p-4">
        <div className="flex flex-col gap-0.5">
          <Label htmlFor="sw-notifications" className="text-sm font-medium">
            Push notifications
          </Label>
          <span className="text-muted-foreground text-xs">
            {notifications ? "Enabled" : "Disabled"}
          </span>
        </div>
        <Switch
          id="sw-notifications"
          checked={notifications}
          onCheckedChange={setNotifications}
          sounds
        />
      </div>

      {/* Group */}
      <div className="flex flex-col gap-3 rounded-lg border p-4">
        {[
          { defaultChecked: true, id: "sw-email", label: "Email digest" },
          { defaultChecked: false, id: "sw-sms", label: "SMS alerts" },
          { defaultChecked: true, id: "sw-slack", label: "Slack messages" },
        ].map(({ id, label, defaultChecked }) => (
          <div key={id} className="flex items-center justify-between">
            <Label htmlFor={id}>{label}</Label>
            <Switch id={id} defaultChecked={defaultChecked} sounds />
          </div>
        ))}
      </div>

      {/* Disabled states */}
      <div className="flex items-center gap-6">
        <div className="flex items-center gap-2">
          <Switch id="sw-dis-off" disabled />
          <Label htmlFor="sw-dis-off" className="text-muted-foreground">
            Off (disabled)
          </Label>
        </div>
        <div className="flex items-center gap-2">
          <Switch id="sw-dis-on" disabled defaultChecked />
          <Label htmlFor="sw-dis-on" className="text-muted-foreground">
            On (disabled)
          </Label>
        </div>
      </div>
    </div>
  );
}


export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-8 bg-background">
      <SwitchDemo />
    </div>
  );
}
